def transform(grid):
    h,w=len(grid),len(grid[0])
    out=[[5 if v==5 else 0 for v in row] for row in grid]
    base={(0,0),(1,0),(1,1),(2,0),(2,1),(2,2),(2,3),(3,0),(3,1),(4,0)}
    shapes=[]
    for k in range(4):
        s=base
        for _ in range(k): s={(c,-r) for r,c in s}
        for flip in (False,True):
            t={(r,-c if flip else c) for r,c in s}
            mr=min(r for r,c in t); mc=min(c for r,c in t)
            t={(r-mr,c-mc) for r,c in t}
            if t not in shapes: shapes.append(t)
    candidates=[]
    for s in shapes:
        sh=max(r for r,c in s)+1; sw=max(c for r,c in s)+1
        for r in range(h-sh+1):
            for c in range(w-sw+1):
                pts={(r+a,c+b) for a,b in s}
                if all(grid[a][b] in (5,8) for a,b in pts):
                    n=sum(grid[a][b]==5 for a,b in pts)
                    if n>=4: candidates.append((n,pts))
    covered=set()
    for n,pts in sorted(candidates,key=lambda x:-x[0]):
        if pts & covered: continue
        for r,c in pts: out[r][c]=5
        covered.update(pts)
    return out

